import assert from 'node:assert/strict';
import fs from 'node:fs/promises';

export async function runMotionPopGridSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));let revision=0;
 async function ready(count=6){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('.nw-pop-card').length===count&&d.querySelector('[data-motion-canvas]')&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},count);}
 async function change(selector,value,count=6){const mark='pop-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.popOld=mark;n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.popOld!==mark&&d.querySelector('.nw-pop-card');},{timeout:10000},mark);await ready(count);}
 async function pose(progress,selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,{progress,gid})=>{const d=f.contentDocument,id=gid||d.querySelector('.sc').dataset.id;f.contentWindow.__NAG_SCROLL_DIRECTOR[id].set(progress);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,src:n.querySelector('img').getAttribute('src'),phase:n.dataset.nwStreamPhase,scale:+n.dataset.nwPopScale,alpha:+n.querySelector('canvas').style.opacity,left:n.style.left,top:n.style.top,width:n.style.width,height:n.style.height}));},{progress,gid});}
 async function actualScroll(selector,gid){await page.$eval(selector,f=>f.contentWindow.scrollTo(0,f.contentDocument.querySelector('.sc').offsetHeight/2-f.contentWindow.innerHeight/2));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()>.4,{},{selector,gid});const middle=await page.$eval(selector,(f,gid)=>({p:f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress(),phase:+f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase}),gid);assert.ok(Math.abs(middle.phase-(middle.p*100-20)/60*3)<.001);await page.$eval(selector,f=>f.contentWindow.scrollTo(0,0));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()<.05,{},{selector,gid});assert.equal(await page.$eval(selector,f=>f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase),'0.000000');}
 async function exported(gid){await page.evaluate(()=>{document.querySelector('#pop-export')?.remove();const f=document.createElement('iframe');f.id='pop-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#pop-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#pop-export').contentDocument.querySelector('.nw-pop-card'),{},gid);}
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,bg:'#527467',elements:[mkEl('label',{text:'Exterior',name:'Exterior'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0]}));
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="pop-grid"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'8');assert.equal(await page.$eval('[data-motion-stream-count]',n=>[n.min,n.max].join(',')),'2,12');assert.equal(await page.$eval('[data-motion-stream="visible"]',n=>n.value),'62');assert.equal(await page.$eval('[data-motion-stream="backgroundType"]',n=>n.value),'none');assert.equal(await page.$('[data-motion-stream="cardRatio"]'),null);
  const start=await pose(0),end=await pose(1);assert.deepEqual(start.map(({phase,...n})=>n),end.map(({phase,...n})=>n));const seen=start.map(()=>({visible:false,fading:false}));for(let i=0;i<20;i++){const cards=await pose(i/20);for(let j=0;j<cards.length;j++){seen[j].visible||=cards[j].alpha===1;seen[j].fading||=cards[j].alpha<.2;}}assert.ok(seen.every(n=>n.visible&&n.fading));assert.ok(new Set((await pose(.15)).map(n=>n.scale)).size>1);await pose(.5);await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/pop-grid-desktop.png'});
  await change('[data-motion-stream-count]','2',2);await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await change('[data-motion-stream-count]','6');assert.deepEqual((await pose(0)).map(n=>[n.id,n.src]),start.map(n=>[n.id,n.src]));await change('[data-motion-stream-count]','12',12);await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),true);await change('[data-motion-stream-count]','6');await change('[data-motion-stream="gap"]','8');await change('[data-motion-stream="visible"]','85');assert.notDeepEqual(await pose(.15),start);await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="turns"]','3');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="scrollLength"]','420');assert.equal((await pose(.1))[0].phase,'0.000000');assert.equal((await pose(.5))[0].phase,'1.500000');assert.equal((await pose(.9))[0].phase,'3.000000');assert.deepEqual((await pose(.1)).map(({phase,...n})=>n),(await pose(.9)).map(({phase,...n})=>n));assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Mi Pop');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.kind,'pop-grid');assert.equal(saved.config.stream.visible,85);assert.equal(saved.assets.length,6);await page.click('[data-motion-saved="'+saved.id+'"]');await ready();const copied=await pose(.35);assert.ok(copied.every(n=>!start.some(o=>o.id===n.id)));assert.deepEqual(copied.map(n=>n.src),start.map(n=>n.src));await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,project:JSON.stringify(project),group:g,outside:sec().elements[0],length:sec().sdLength,enabled:sec().sdEnabled};});assert.equal(inserted.enabled,true);assert.equal(inserted.length,420);assert.equal(inserted.group.bg,'transparent');assert.deepEqual(inserted.outside,before.outside);await page.waitForFunction(id=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id]&&document.querySelector('#preview').contentDocument.querySelector('.nw-pop-card'),{},inserted.gid);await actualScroll('#preview',inserted.gid);await exported(inserted.gid);assert.deepEqual((await pose(.35,'#pop-export',inserted.gid)).map(n=>n.src),copied.map(n=>n.src));await page.$eval('#pop-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].live(),inserted.gid);await actualScroll('#pop-export',inserted.gid);await page.evaluate(()=>document.querySelector('#pop-export').remove());
  await page.evaluate(id=>{NAGWEB_SCROLL_DIRECTOR.scrub(id,.25);NAGWEB_MOTION_LAB.edit(id);},inserted.gid);await ready();await change('[data-motion-stream="visible"]','58');await page.$eval('#preview',f=>f.contentDocument.body.dataset.popSaved='old');await page.click('[data-motion-save]');await page.waitForFunction(id=>{const f=document.querySelector('#preview');return f?.contentDocument?.body&&!f.contentDocument.body.dataset.popSaved&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[id]&&f.contentDocument.querySelector('.nw-pop-card');},{},inserted.gid);await actualScroll('#preview',inserted.gid);const scroll=await page.evaluate(()=>JSON.stringify(project));
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();assert.equal(await page.$eval('[data-motion-stream="visible"]',n=>n.value),'58');await change('[data-motion-config="source"]','time');await change('[data-motion-config="duration"]','2');await page.click('[data-motion-save]');const loop=await page.evaluate(()=>JSON.stringify(project));assert.equal(await page.evaluate(()=>sec().sdEnabled),false);await exported(inserted.gid);const clock=await page.$eval('#pop-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].progress(),inserted.gid);await page.waitForFunction(({gid,clock})=>document.querySelector('#pop-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()!==clock,{timeout:3000},{gid:inserted.gid,clock});assert.equal(await page.$eval('#pop-export',f=>!!f.contentDocument.querySelector('.nw-sd-active')),false);await page.evaluate(()=>document.querySelector('#pop-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),scroll);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);assert.equal(await page.evaluate(id=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.id===id).nwMotionInstance.stream.kind,inserted.gid),'pop-grid');
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="pop-grid"]');await ready();await change('[data-motion-stream="frameRatio"]','auto');await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/pop-grid-mobile.png'});await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);assert.deepEqual(await pose(.1),await pose(.9));await page.emulateMediaFeatures([]);await page.click('[data-motion-close]');await page.setViewport(viewport);assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="pop-grid"]');await ready();await page.click('[data-motion-insert]');const newScene=await page.evaluate(()=>({gid:sec().nwMotionSceneGroup,config:sec().elements.find(e=>e.nwMotionInstance).nwMotionInstance}));assert.equal(newScene.config.template,'pop-grid');assert.ok(newScene.gid);await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),newScene.gid);await ready();await page.click('[data-motion-close]');
  console.log('Pop Grid: ritmos independientes y cierre exacto, cantidad 2–12 y recuperación de imágenes, controles/borrador/Biblioteca con IDs nuevos, scroll real tras guardar, loop sin Director, transparencia, historial/JSON/exportación, inserción como escena reeditable, móvil y movimiento reducido OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/pop-grid-failure.png'}).catch(()=>{});throw error;}finally{await page.emulateMediaFeatures([]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#pop-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}
